// ModuleNames + TableModel → house-style module source text. Transcribes the
// worked example in docs/GUIDE-api-development.md Section 1 (the public posts
// module) generically. Pure text builders — the CLI runs biome afterwards.

import type { ColumnModel, TableModel } from "../schema-gen/introspect";
import { kebabCase, titleCase } from "../schema-gen/naming";
import type { ModuleNames } from "./names";

/** Columns that must never reach a public wire, whatever the schema says. */
const SENSITIVE_NAME_RE = /password|hash|secret|token/i;

const GENERATED_HEADER = [
  "// Generated by scripts/generate-module.ts — review the TODO(generator)",
  "// comments before shipping. Regenerating with --force discards hand edits.",
];

export interface PublicColumns {
  /** Table columns exposed on the public wire, in output-schema order. */
  columns: ColumnModel[];
  /** Output-schema keys with no table column — serializer TODOs (typecheck fails loudly). */
  extraInSchema: string[];
  /** Sensitive-looking columns dropped even though the schema exposes them. */
  skipped: string[];
}

/**
 * The public surface = the model's output-schema shape intersected with the
 * table's columns (the same source detectDrift reads), minus anything
 * sensitive-looking. Schema order wins so the serializer reads like the schema.
 */
export function selectPublicColumns(model: TableModel, schemaShapeKeys: string[]): PublicColumns {
  const byName = new Map(model.columns.map((column) => [column.name, column]));
  const columns: ColumnModel[] = [];
  const extraInSchema: string[] = [];
  const skipped: string[] = [];
  for (const key of schemaShapeKeys) {
    const column = byName.get(key);
    if (!column) {
      extraInSchema.push(key);
    } else if (SENSITIVE_NAME_RE.test(key)) {
      skipped.push(key);
    } else {
      columns.push(column);
    }
  }
  return { columns, extraInSchema, skipped };
}

/** Columns the public list contract can reference (the allow-list entries). */
export function listableColumns(publicColumns: PublicColumns): ColumnModel[] {
  return publicColumns.columns.filter((column) => {
    if (column.kind === "id" || column.kind === "unknown" || column.kind === "uuid") return false;
    if (column.kind === "timestamp") return column.auto && column.name === "createdAt";
    return true;
  });
}

// ---------------------------------------------------------------------------
// packages/schemas/src/<fileBase>.ts — appended public allow-list
// ---------------------------------------------------------------------------

export function emitPublicFieldsBlock(names: ModuleNames, publicColumns: PublicColumns): string {
  const lines: string[] = [
    "",
    `// What the PUBLIC ${names.moduleName} list endpoint accepts (consumed by`,
    `// apps/api/src/modules/${names.moduleName}). Deliberately its own allow-list —`,
    `// the admin ${names.fileBase} fields are too much surface for an app-facing endpoint.`,
    "// TODO(generator): trim this list — drop anything the public API should not",
    "// search, filter, or sort by.",
    `export const ${names.publicFieldsName}: ResourceField[] = [`,
  ];
  for (const column of listableColumns(publicColumns)) {
    const label = titleCase(column.name);
    switch (column.kind) {
      case "enum":
        lines.push(
          `  { name: ${JSON.stringify(column.name)}, type: "enum", label: ${JSON.stringify(label)}, options: [${column.values.map((value) => JSON.stringify(value)).join(", ")}], filterable: true },`,
        );
        break;
      case "relation":
        lines.push(
          `  { name: ${JSON.stringify(column.name)}, type: "relation", label: ${JSON.stringify(label.replace(/ Id$/, ""))}, resource: ${JSON.stringify(kebabCase(column.targetTableName))}, displayField: ${JSON.stringify(column.displayField)}, filterable: true },`,
        );
        break;
      case "boolean":
        lines.push(
          `  { name: ${JSON.stringify(column.name)}, type: "boolean", label: ${JSON.stringify(label)}, filterable: true },`,
        );
        break;
      case "int":
      case "number":
        lines.push(
          `  { name: ${JSON.stringify(column.name)}, type: "number", label: ${JSON.stringify(label)}, filterable: true },`,
        );
        break;
      case "timestamp":
        lines.push(
          `  { name: ${JSON.stringify(column.name)}, type: "date", label: "Created", sortable: true },`,
        );
        break;
      default: {
        // string / email / url / image / text / richtext — searchable text.
        const type =
          column.kind === "text" || column.kind === "richtext" || column.kind === "image"
            ? column.kind
            : "string";
        lines.push(
          `  { name: ${JSON.stringify(column.name)}, type: ${JSON.stringify(type)}, label: ${JSON.stringify(label)}, searchable: true },`,
        );
      }
    }
  }
  lines.push("];", "");
  return lines.join("\n");
}

// ---------------------------------------------------------------------------
// <name>.repo.ts
// ---------------------------------------------------------------------------

export function emitRepoFile(names: ModuleNames, publicColumns: PublicColumns): string {
  const table = names.tableKey;
  const rowType = `${names.modelType}Row`;
  const columnEntries = [
    `  // id is implicitly filterable (eq/in) by parseListQuery.`,
    `  id: ${table}.id,`,
    ...listableColumns(publicColumns).map((column) => `  ${column.name}: ${table}.${column.name},`),
  ];

  return [
    ...GENERATED_HEADER,
    "",
    'import { and, asc, desc, eq, gte, ilike, inArray, lte, type SQL, sql } from "drizzle-orm";',
    'import type { PgColumn } from "drizzle-orm/pg-core";',
    'import type { Db } from "@/db/client";',
    `import { ${table} } from "@/db/schema";`,
    'import type { ListFilter, ListQuery } from "@/lib/pagination";',
    "",
    `type ${rowType} = typeof ${table}.$inferSelect;`,
    "",
    `// The repo-side mirror of ${names.publicFieldsName}: only these columns are`,
    "// reachable from the public query contract. parseListQuery already",
    "// allow-listed the request, so a miss here means the two lists drifted —",
    "// fail loudly.",
    "const columns: Record<string, PgColumn> = {",
    ...columnEntries,
    "};",
    "",
    "function column(field: string): PgColumn {",
    "  const col = columns[field];",
    `  if (!col) throw new Error(\`Column not exposed to the public ${names.moduleName} API: \${field}\`);`,
    "  return col;",
    "}",
    "",
    "// ILIKE's %/_ are wildcards; filter values are data, so escape them.",
    "function escapeLike(value: string): string {",
    '  return value.replace(/[\\\\%_]/g, "\\\\$&");',
    "}",
    "",
    "// Filter values arrive as validated strings; timestamp columns are the one",
    "// case Drizzle won't coerce itself.",
    "function driverValue(col: PgColumn, value: string): string | Date {",
    '  return col.dataType === "date" ? new Date(value) : value;',
    "}",
    "",
    "function toCondition(filter: ListFilter) {",
    "  const col = column(filter.field);",
    "  switch (filter.op) {",
    '    case "eq":',
    "      return eq(col, driverValue(col, filter.value as string));",
    '    case "like":',
    // biome-ignore lint/suspicious/noTemplateCurlyInString: emitted source, the placeholder belongs to the generated file
    "      return ilike(col, `%${escapeLike(filter.value as string)}%`);",
    '    case "in":',
    "      return inArray(col, (filter.value as string[]).map((v) => driverValue(col, v)));",
    '    case "gte":',
    "      return gte(col, driverValue(col, filter.value as string));",
    '    case "lte":',
    "      return lte(col, driverValue(col, filter.value as string));",
    "  }",
    "}",
    "",
    `export function ${names.repoFactory}(db: Db) {`,
    "  // Shared list machinery: WHERE + stable ORDER BY + LIMIT/OFFSET + COUNT.",
    "  async function listWhere(base: SQL | undefined, query: ListQuery) {",
    "    const where = and(",
    "      ...(base ? [base] : []),",
    "      ...query.filters.map((filter) => toCondition(filter)),",
    "    );",
    "    // Trailing id tiebreaker keeps pagination stable when the requested sort",
    "    // has duplicate values (or no sort was requested at all).",
    "    const orderBy = [",
    '      ...query.sort.map((s) => (s.dir === "desc" ? desc(column(s.field)) : asc(column(s.field)))),',
    `      asc(${table}.id),`,
    "    ];",
    "",
    "    const rows = await db",
    "      .select()",
    `      .from(${table})`,
    "      .where(where)",
    "      .orderBy(...orderBy)",
    "      .limit(query.pageSize)",
    "      .offset((query.page - 1) * query.pageSize);",
    "",
    "    // count(*)::int — postgres.js returns bigint counts as strings.",
    "    const [counted] = await db",
    "      .select({ total: sql<number>`count(*)::int` })",
    `      .from(${table})`,
    "      .where(where);",
    "",
    "    return { rows, total: counted?.total ?? 0 };",
    "  }",
    "",
    "  // TODO(generator): these expose ALL rows. Encode visibility rules in repo",
    "  // method semantics (e.g. rename to listPublished/findPublishedById with a",
    "  // base condition) before shipping anything with restricted rows — see the",
    "  // posts example in docs/GUIDE-api-development.md.",
    "  return {",
    `    list(query: ListQuery): Promise<{ rows: ${rowType}[]; total: number }> {`,
    "      return listWhere(undefined, query);",
    "    },",
    "",
    `    async findById(id: string): Promise<${rowType} | undefined> {`,
    `      const [row] = await db.select().from(${table}).where(eq(${table}.id, id)).limit(1);`,
    "      return row;",
    "    },",
    "  };",
    "}",
    "",
    `export type ${names.repoType} = ReturnType<typeof ${names.repoFactory}>;`,
    "",
  ].join("\n");
}

// ---------------------------------------------------------------------------
// <name>.service.ts
// ---------------------------------------------------------------------------

export function emitServiceFile(names: ModuleNames): string {
  return [
    ...GENERATED_HEADER,
    "",
    'import { NotFoundError } from "@/lib/errors";',
    'import type { ListQuery } from "@/lib/pagination";',
    `import type { ${names.repoType} } from "./${names.moduleName}.repo";`,
    "",
    `export interface ${names.serviceType}Deps {`,
    `  ${names.repoKey}: ${names.repoType};`,
    "}",
    "",
    "// TODO(generator): add business rules here (ownership, visibility, writes).",
    "// Services throw AppError subclasses and never import Hono.",
    `export function ${names.serviceFactory}(deps: ${names.serviceType}Deps) {`,
    `  const { ${names.repoKey} } = deps;`,
    "",
    "  return {",
    "    async list(query: ListQuery) {",
    `      return ${names.repoKey}.list(query);`,
    "    },",
    "",
    "    async getById(id: string) {",
    `      const ${names.singularCamel} = await ${names.repoKey}.findById(id);`,
    '      // "Exists but you may not see it" and "does not exist" must look identical.',
    `      if (!${names.singularCamel}) throw new NotFoundError(${JSON.stringify(`${names.modelType} not found`)});`,
    `      return ${names.singularCamel};`,
    "    },",
    "  };",
    "}",
    "",
    `export type ${names.serviceType} = ReturnType<typeof ${names.serviceFactory}>;`,
    "",
  ].join("\n");
}

// ---------------------------------------------------------------------------
// <name>.routes.ts
// ---------------------------------------------------------------------------

export interface RoutesOptions {
  isProtected: boolean;
}

/** One `key: row.key,` line per public column; Dates become ISO strings. */
function serializerLines(publicColumns: PublicColumns): string[] {
  const lines: string[] = [];
  for (const column of publicColumns.columns) {
    if (column.kind === "timestamp") {
      lines.push(
        column.notNull
          ? `    ${column.name}: row.${column.name}.toISOString(),`
          : `    ${column.name}: row.${column.name} ? row.${column.name}.toISOString() : null,`,
      );
    } else {
      if (column.note) lines.push(`    // TODO(generator): ${column.note}`);
      lines.push(`    ${column.name}: row.${column.name},`);
    }
  }
  for (const key of publicColumns.extraInSchema) {
    lines.push(
      `    // TODO(generator): ${JSON.stringify(key)} is in the output schema but has no`,
      "    // table column — map it by hand (this typecheck error is deliberate).",
    );
  }
  return lines;
}

export function emitRoutesFile(
  names: ModuleNames,
  publicColumns: PublicColumns,
  options: RoutesOptions,
): string {
  const { isProtected } = options;
  const security = isProtected ? ["  security: [{ bearerAuth: [] }],"] : [];
  const unauthorized = isProtected
    ? ['    401: errorResponse("Missing, invalid, or expired access token"),']
    : [];

  return [
    ...GENERATED_HEADER,
    "",
    'import { createRoute, z } from "@hono/zod-openapi";',
    "import {",
    `  type ${names.modelType},`,
    `  ${names.schemaName},`,
    "  envelope,",
    "  listEnvelope,",
    `  ${names.publicFieldsName},`,
    '} from "@starter/schemas";',
    `import { ${names.tableKey} } from "@/db/schema";`,
    'import { createRouter, errorResponse, jsonContent } from "@/lib/openapi";',
    'import { parseListQuery } from "@/lib/pagination";',
    ...(isProtected ? ['import { authMiddleware } from "@/middleware/auth";'] : []),
    `import type { ${names.serviceType} } from "./${names.moduleName}.service";`,
    "",
    `type ${names.modelType}Row = typeof ${names.tableKey}.$inferSelect;`,
    "",
    "const IdParamsSchema = z.object({ id: z.uuid() });",
    "",
    "// Documents the list convention for OpenAPI. filter[field][op] keys can't be",
    "// a static Zod shape, so real validation lives in parseListQuery (which also",
    "// allow-lists fields); this schema is deliberately permissive.",
    "const ListQueryDocSchema = z.object({",
    '  page: z.string().optional().openapi({ example: "1" }),',
    '  pageSize: z.string().optional().openapi({ example: "20", description: "Max 100" }),',
    '  sort: z.string().optional().openapi({ example: "createdAt:desc" }),',
    "});",
    "",
    "// Dates cross the wire as ISO strings. Mapping explicitly (instead of relying",
    `// on JSON.stringify) keeps the handler return type aligned with ${names.schemaName},`,
    "// so drift is a compile error.",
    `function ${names.serializerName}(row: ${names.modelType}Row): ${names.modelType} {`,
    "  return {",
    ...serializerLines(publicColumns),
    "  };",
    "}",
    "",
    `const list${names.pluralPascal}Route = createRoute({`,
    '  method: "get",',
    '  path: "/",',
    `  tags: [${JSON.stringify(names.moduleName)}],`,
    `  summary: ${JSON.stringify(`List ${names.moduleName}`)},`,
    "  description:",
    '    "Query convention: `page`, `pageSize` (max 100), `sort=createdAt:desc`, " +',
    '    "`filter[field][op]=value` with ops eq|like|in|gte|lte.",',
    ...security,
    "  request: { query: ListQueryDocSchema },",
    "  responses: {",
    `    200: jsonContent(listEnvelope(${names.schemaName}), ${JSON.stringify(`A page of ${names.moduleName}`)}),`,
    '    400: errorResponse("Invalid list query"),',
    ...unauthorized,
    "  },",
    "});",
    "",
    `const get${names.modelType}Route = createRoute({`,
    '  method: "get",',
    '  path: "/{id}",',
    `  tags: [${JSON.stringify(names.moduleName)}],`,
    `  summary: ${JSON.stringify(`Get one ${names.singularLabel}`)},`,
    ...security,
    "  request: { params: IdParamsSchema },",
    "  responses: {",
    `    200: jsonContent(envelope(${names.schemaName}), ${JSON.stringify(`The ${names.singularLabel}`)}),`,
    '    400: errorResponse("Invalid id"),',
    `    404: errorResponse(${JSON.stringify(`No ${names.singularLabel} with that id`)}),`,
    ...unauthorized,
    "  },",
    "});",
    "",
    `export function ${names.routesFactory}(service: ${names.serviceType}) {`,
    "  const router = createRouter();",
    ...(isProtected
      ? [
          "",
          "  // Whole-router auth: every route below requires a bearer access token",
          "  // (the `security` entries above are the OpenAPI documentation half).",
          "  router.use(authMiddleware());",
        ]
      : []),
    "",
    "  // TODO(generator): add write endpoints (POST/PATCH/DELETE) by hand — they",
    "  // carry business rules a generator can't guess. Register static paths",
    '  // (e.g. "/mine") BEFORE "/{id}" — Hono matches in registration order.',
    `  router.openapi(list${names.pluralPascal}Route, async (c) => {`,
    `    const query = parseListQuery(c.req.query(), ${names.publicFieldsName});`,
    "    const { rows, total } = await service.list(query);",
    "    return c.json(",
    "      {",
    `        data: rows.map(${names.serializerName}),`,
    "        meta: { page: query.page, pageSize: query.pageSize, total },",
    "      },",
    "      200,",
    "    );",
    "  });",
    "",
    `  router.openapi(get${names.modelType}Route, async (c) => {`,
    `    const ${names.singularCamel} = await service.getById(c.req.valid("param").id);`,
    `    return c.json({ data: ${names.serializerName}(${names.singularCamel}) }, 200);`,
    "  });",
    "",
    "  return router;",
    "}",
    "",
  ].join("\n");
}

// ---------------------------------------------------------------------------
// tests/unit/<name>-service.test.ts
// ---------------------------------------------------------------------------

export function emitUnitTestFile(names: ModuleNames): string {
  return [
    ...GENERATED_HEADER,
    "",
    'import "../setup";',
    'import { describe, expect, test } from "bun:test";',
    'import { NotFoundError } from "@/lib/errors";',
    'import type { ListQuery } from "@/lib/pagination";',
    `import type { ${names.repoType} } from "@/modules/${names.moduleName}/${names.moduleName}.repo";`,
    `import { ${names.serviceFactory} } from "@/modules/${names.moduleName}/${names.moduleName}.service";`,
    "",
    `const fakeRepo: ${names.repoType} = {`,
    "  list: async () => ({ rows: [], total: 0 }),",
    "  findById: async () => undefined,",
    "};",
    "",
    `describe(${JSON.stringify(`${names.moduleName} service`)}, () => {`,
    '  test("getById throws NotFoundError for unknown ids", async () => {',
    `    const service = ${names.serviceFactory}({ ${names.repoKey}: fakeRepo });`,
    "    await expect(service.getById(crypto.randomUUID())).rejects.toBeInstanceOf(NotFoundError);",
    "  });",
    "",
    '  test("list passes the parsed query through to the repo", async () => {',
    "    const queries: ListQuery[] = [];",
    `    const service = ${names.serviceFactory}({`,
    `      ${names.repoKey}: {`,
    "        ...fakeRepo,",
    "        list: async (query: ListQuery) => {",
    "          queries.push(query);",
    "          return { rows: [], total: 0 };",
    "        },",
    "      },",
    "    });",
    "    const query: ListQuery = { page: 2, pageSize: 5, sort: [], filters: [] };",
    "    await service.list(query);",
    "    expect(queries).toEqual([query]);",
    "  });",
    "});",
    "",
  ].join("\n");
}

// ---------------------------------------------------------------------------
// tests/e2e/<name>-e2e.test.ts
// ---------------------------------------------------------------------------

export function emitE2eTestFile(names: ModuleNames, options: RoutesOptions): string {
  const { isProtected } = options;
  const base = `/api/${names.moduleName}`;
  const headers = isProtected ? ", { headers: AUTH }" : "";

  return [
    ...GENERATED_HEADER,
    "",
    'import "../setup";',
    'import { afterAll, describe, expect, test } from "bun:test";',
    'import { drizzle } from "drizzle-orm/postgres-js";',
    ...(isProtected ? ['import { sign } from "hono/jwt";'] : []),
    'import { createApp } from "@/app";',
    'import { env } from "@/config/env";',
    'import { createPool } from "@/db/client";',
    'import * as schema from "@/db/schema";',
    `import { ${names.repoFactory} } from "@/modules/${names.moduleName}/${names.moduleName}.repo";`,
    `import { ${names.serviceFactory} } from "@/modules/${names.moduleName}/${names.moduleName}.service";`,
    'import { prepareTestDatabase } from "../helpers/test-db";',
    "",
    "// Generated scaffold: every assertion here is seed-free — the test database",
    "// is shared between suites, so only envelope shapes are asserted, never row",
    "// counts. Add seeded scenarios for your real business rules by hand.",
    "await prepareTestDatabase();",
    "",
    "const pool = createPool(env.DATABASE_URL);",
    "const db = drizzle(pool, { schema });",
    "",
    "const app = createApp({",
    `  ${names.serviceKey}: ${names.serviceFactory}({ ${names.repoKey}: ${names.repoFactory}(db) }),`,
    "  // E2e suites fire more requests than the strict production limits allow.",
    "  rateLimit: {",
    "    auth: { windowMs: 60_000, limit: 1_000 },",
    "    global: { windowMs: 60_000, limit: 10_000 },",
    "  },",
    "});",
    "",
    ...(isProtected
      ? [
          "// authMiddleware only verifies the JWT (no DB lookup), so a freshly minted",
          "// token with a random subject exercises the protected routes without seeds.",
          "const accessToken = await sign(",
          '  { sub: crypto.randomUUID(), type: "access", exp: Math.floor(Date.now() / 1000) + 900 },',
          "  env.JWT_SECRET,",
          ");",
          // biome-ignore lint/suspicious/noTemplateCurlyInString: emitted source, the placeholder belongs to the generated file
          "const AUTH = { authorization: `Bearer ${accessToken}` };",
          "",
        ]
      : []),
    "afterAll(async () => {",
    "  await pool.end({ timeout: 5 });",
    "});",
    "",
    `describe(${JSON.stringify(`${names.moduleName} e2e`)}, () => {`,
    ...(isProtected
      ? [
          '  test("requests without a bearer token get the 401 envelope", async () => {',
          `    const res = await app.request(${JSON.stringify(base)});`,
          "    expect(res.status).toBe(401);",
          "    const body = (await res.json()) as { error: { code: string } };",
          '    expect(body.error.code).toBe("UNAUTHORIZED");',
          "  });",
          "",
        ]
      : []),
    `  test("GET ${base} returns the list envelope", async () => {`,
    `    const res = await app.request(${JSON.stringify(base)}${headers});`,
    "    expect(res.status).toBe(200);",
    "    const body = (await res.json()) as {",
    "      data: unknown[];",
    "      meta: { page: number; pageSize: number; total: number };",
    "    };",
    "    expect(Array.isArray(body.data)).toBe(true);",
    "    expect(body.meta.page).toBe(1);",
    "    expect(body.meta.pageSize).toBe(20);",
    "    expect(body.meta.total).toBeGreaterThanOrEqual(0);",
    "  });",
    "",
    '  test("an unknown id returns the 404 envelope", async () => {',
    "    // A random uuid is astronomically unlikely to exist in the shared test DB.",
    `    const res = await app.request(\`${base}/\${crypto.randomUUID()}\`${headers});`,
    "    expect(res.status).toBe(404);",
    "    const body = (await res.json()) as { error: { code: string } };",
    '    expect(body.error.code).toBe("NOT_FOUND");',
    "  });",
    "",
    '  test("a non-uuid id is rejected at the boundary with 400", async () => {',
    `    const res = await app.request(${JSON.stringify(`${base}/not-a-uuid`)}${headers});`,
    "    expect(res.status).toBe(400);",
    "    const body = (await res.json()) as { error: { code: string } };",
    '    expect(body.error.code).toBe("VALIDATION_ERROR");',
    "  });",
    "",
    '  test("an undeclared sort field is rejected with 400", async () => {',
    `    const res = await app.request(${JSON.stringify(`${base}?sort=definitelyNotAField:asc`)}${headers});`,
    "    expect(res.status).toBe(400);",
    "  });",
    "",
    '  test("pageSize is capped at 100", async () => {',
    `    const res = await app.request(${JSON.stringify(`${base}?pageSize=5000`)}${headers});`,
    "    expect(res.status).toBe(400);",
    "  });",
    "});",
    "",
  ].join("\n");
}
